// ============================================================
// Helpers
// ============================================================

static void expectDoubleNanEq(double a, double b, const char* label, std::size_t i) {
    if (std::isnan(a)) {
        EXPECT_TRUE(std::isnan(b)) << label << " at i=" << i << ": Expected NaN, got " << b;
    } else if (std::isnan(b)) {
        EXPECT_TRUE(std::isnan(a)) << label << " at i=" << i << ": Expected " << a << ", got NaN";
    } else {
        EXPECT_NEAR(a, b, 1e-12) << label << " at i=" << i << ": Values differ";
    }
}

// ============================================================
// Test fixture
// ============================================================

class RollingOpPandasCrossValidate : public ::testing::Test {
protected:
    template <typename Op, typename... Args>
    void check(const double* ref, const char* label, Args&&... args) {
        Op op(std::forward<Args>(args)...);
        double output[kN];
        op.evaluate(ColView<double>(kInput, kN), output);
        for (std::size_t i = 0; i < kN; ++i) {
            expectDoubleNanEq(output[i], ref[i], label, i);
        }
    }
};

// ============================================================
// Tests — one per operator, grouped by category
// ============================================================

// --- Window statistics ---
TEST_F(RollingOpPandasCrossValidate, RollingSum)   { check<RollingSumOp>(kSumW3, "rolling_sum(w=3)", 3); }
