// --- Quantile (extra q parameter) ---
TEST_F(RollingOpPandasCrossValidate, RollingQuantile) {
    double output[kN];
    RollingQuantileOp(4, 0.25).evaluate(ColView<double>(kInput, kN), output);
    for (std::size_t i = 0; i < kN; ++i)
        expectDoubleNanEq(output[i], kQuantileQ25W4[i], "rolling_quantile(w=4,q=0.25)", i);

    RollingQuantileOp(4, 0.50).evaluate(ColView<double>(kInput, kN), output);
    for (std::size_t i = 0; i < kN; ++i)
        expectDoubleNanEq(output[i], kQuantileQ50W4[i], "rolling_quantile(w=4,q=0.50)", i);

    RollingQuantileOp(4, 0.75).evaluate(ColView<double>(kInput, kN), output);
    for (std::size_t i = 0; i < kN; ++i)
        expectDoubleNanEq(output[i], kQuantileQ75W4[i], "rolling_quantile(w=4,q=0.75)", i);
}

